import java.util.*;
import java.io.*;

public class Main {
    static final int B = 1000000;
    static final int mod1 = 998244353;
    static final int mod2 = 1000000007;

    static long n, cnt;
    static List<Integer>[] v = new ArrayList[10];
    static long[] sum = new long[10];
    static int ans, tot;

    static {
        for (int i = 0; i < 10; i++) {
            v[i] = new ArrayList<>();
        }
    }

    static int calc(long x) {
        return (int)((x % mod1 + mod1) % mod1);
    }

    static void dfs1(int dep, int num) {
        cnt++;
        v[dep].add(calc(cnt - num));
        if (dep == 6) return;
        for (int i = 0; i <= 9; i++) {
            dfs1(dep + 1, num * 10 + i);
        }
    }

    static void dfs2(int dep, long num) {
        if (num > n) return;
        if (dep >= 1) {
            if (num * B > n / 10 && (num + 1) * B - 1 <= n) {
                int tmp = 1;
                for (int i = 0; i <= 6; i++, tmp *= 10) {
                    int w = calc(cnt - tmp * (int)num);
                    int pos = lowerBound(v[i], mod1 - w);
                    ans = (int)((ans + 1L * w * v[i].size() + sum[i] - 1L * mod2 * (v[i].size() - pos)) % mod2);
                }
                cnt += tot;
                return;
            }
            cnt++;
            ans = (int)((ans + calc(cnt - num)) % mod2);
        }
        int start = (dep == 0) ? 1 : 0;
        for (int i = start; i <= 9; i++) {
            dfs2(dep + 1, num * 10 + i);
        }
    }

    static int lowerBound(List<Integer> list, int target) {
        int low = 0, high = list.size();
        while (low < high) {
            int mid = (low + high) / 2;
            if (list.get(mid) >= target) {
                high = mid;
            } else {
                low = mid + 1;
            }
        }
        return low;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        n = Long.parseLong(br.readLine().trim());
        dfs1(0, 0);
        for (int i = 0; i <= 6; i++) {
            Collections.sort(v[i]);
            long totalSum = 0;
            for (int val : v[i]) {
                totalSum += val;
            }
            sum[i] = totalSum % mod2;
        }
        tot = (int) cnt;
        cnt = 0;
        ans = 0;
        dfs2(0, 0);
        System.out.println((ans + mod2) % mod2);
    }
}
